const body = $('Webhook').first().json.body;

// Валидация входных данных
const evaluatorId = parseInt(body.evaluator_id);
const subjectId = parseInt(body.subject_id);
const criteriaId = parseInt(body.criteria_id);
const correctionScore = parseInt(body.correction_score);
// Опционально: явно указать уровень корректировки
const explicitLevel = body.correction_level || null;

if (!evaluatorId || !subjectId || !criteriaId || isNaN(correctionScore)) {
  throw new Error('Missing required fields: evaluator_id, subject_id, criteria_id, correction_score');
}

if (correctionScore < 1 || correctionScore > 10) {
  throw new Error('correction_score must be between 1 and 10');
}

return {
  json: {
    evaluator_id: evaluatorId,
    subject_id: subjectId,
    criteria_id: criteriaId,
    correction_score: correctionScore,
    explicit_level: explicitLevel
  }
};

const permissionData = $input.first().json;
const inputData = $('Validate Input').first().json;

const correctionLevel = inputData.explicit_level || permissionData.correction_level;

// Проверяем права доступа
if (correctionLevel === 'none') {
  throw new Error('Access denied: You can only correct scores if you are the manager\'s manager (mid_level) or C-level/admin');
}

// C-level и admin всегда могут ставить c_level корректировку
// Менеджеры менеджеров могут ставить mid_level корректировку
const allowedLevels = ['mid_level', 'c_level'];
if (!allowedLevels.includes(correctionLevel)) {
  throw new Error('Invalid correction level: ' + correctionLevel);
}

return { 
  json: {
    ...inputData,
    correction_level: correctionLevel
  }
};

const result = $input.first().json;
const inputData = $('Validate Input').first().json;

return {
  json: {
    success: true,
    message: 'Score correction saved successfully',
    data: {
      id: result.id,
      subject_id: inputData.subject_id,
      criteria_id: inputData.criteria_id,
      correction_score: result.correction_score,
      correction_level: result.correction_level
    }
  }
};
